-- V90.fj: Reliability Executive Governance Learning / Cross-Period Trend & Escalation Effectiveness
-- Schema target: 236
CREATE TABLE IF NOT EXISTS maintenance_reliability_governance_learning_snapshot (snapshot_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, period_key TEXT NOT NULL, prior_period_key TEXT, current_score NUMERIC NOT NULL DEFAULT 0, prior_score NUMERIC NOT NULL DEFAULT 0, score_delta NUMERIC NOT NULL DEFAULT 0, current_resolution_rate NUMERIC NOT NULL DEFAULT 0, prior_resolution_rate NUMERIC NOT NULL DEFAULT 0, resolution_delta NUMERIC NOT NULL DEFAULT 0, current_effectiveness_rate NUMERIC NOT NULL DEFAULT 0, prior_effectiveness_rate NUMERIC NOT NULL DEFAULT 0, effectiveness_delta NUMERIC NOT NULL DEFAULT 0, overdue_escalation_count INTEGER NOT NULL DEFAULT 0, recurring_escalation_count INTEGER NOT NULL DEFAULT 0, assessment TEXT NOT NULL DEFAULT 'NO_BASELINE', recommendation TEXT, status TEXT NOT NULL DEFAULT 'OPEN', created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id,entity_id,period_key));
CREATE TABLE IF NOT EXISTS maintenance_reliability_governance_learning_recommendation (recommendation_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, period_key TEXT NOT NULL, recommendation_type TEXT NOT NULL, finding TEXT NOT NULL, proposed_improvement TEXT NOT NULL, evidence_note TEXT NOT NULL, owner_user_id TEXT, due_date DATE, status TEXT NOT NULL DEFAULT 'OPEN', resolved_by TEXT, resolved_at TIMESTAMP, created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS maintenance_reliability_governance_learning_close (close_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, period_key TEXT NOT NULL, recommendation_count INTEGER NOT NULL DEFAULT 0, open_recommendation_count INTEGER NOT NULL DEFAULT 0, learning_score NUMERIC NOT NULL DEFAULT 0, closed_by TEXT NOT NULL, closure_note TEXT, closed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id,entity_id,period_key));
CREATE INDEX IF NOT EXISTS ix_rel_gov_learning_scope ON maintenance_reliability_governance_learning_snapshot(organization_id,entity_id,period_key,status);
CREATE INDEX IF NOT EXISTS ix_rel_gov_learning_rec ON maintenance_reliability_governance_learning_recommendation(organization_id,entity_id,period_key,status);
